### Example

```javascript
function greet(city) {
  console.log(this.name, city);
}

const user = { name: "John" };
const fn = greet.myBind(user);
fn("London"); // John London
```

Complete the implementation in the editor.

questions.template:
Function.prototype.myBind = function (context, ...presetArgs) {
  // Write your code here
};

questions.explanation:
### Solution

```javascript
Function.prototype.myBind = function (context, ...presetArgs) {
  const fn = this;
  return function (...laterArgs) {
    return fn.apply(context, [...presetArgs, ...laterArgs]);
  };
};
```

questions.description:
Implement `deepCopy(obj)` that creates an independent clone of objects and arrays.

### Example

```javascript
const a = { x: 1, y: { z: 2 } };
const b = deepCopy(a);
b.y.z = 100;
console.log(a.y.z); // 2
```

Mutating the copy must not affect the original. Complete the implementation in the editor.

questions.template:
function deepCopy(obj) {
  // Write your code here
}

questions.explanation:
### Solution

```javascript
function deepCopy(obj) {
  if (obj === null || typeof obj !== "object") return obj;
  const copy = Array.isArray(obj) ? [] : {};
  for (const key in obj) {
    if (Object.hasOwn(obj, key)) copy[key] = deepCopy(obj[key]);
  }
  return copy;
}
```

