### Solution

```javascript
function flatten(arr, depth = 1) {
  if (depth === 0) return arr.slice();
  const result = [];
  for (const item of arr) {
    if (Array.isArray(item)) result.push(...flatten(item, depth - 1));
    else result.push(item);
  }
  return result;
}
```

questions.description:
Implement `debounce(fn, delay)` that delays calling `fn` until `delay` ms have passed since the last invocation.

### Example

```javascript
window.addEventListener("resize", debounce(() => {
  console.log("resize");
}, 300));
```

Complete the implementation in the editor.

questions.template:
function debounce(fn, delay) {
  // Write your code here
}

questions.explanation:
### Solution

```javascript
function debounce(fn, delay) {
  let timer;
  return function (...args) {
    clearTimeout(timer);
    timer = setTimeout(() => fn.apply(this, args), delay);
  };
}
```

